/// <summary>
/// Design-time stub implementation of the projection members on
/// <see cref="ISettingsTabViewModel"/>. The main <c>DesignSettingsTabViewModel</c>
/// class is auto-generated by <c>LocalizedStringsGenerator</c> into a separate
/// <c>.g.cs</c> file; this partial extends it with the hand-written interface members
/// so the AXAML previewer resolves all compiled bindings without errors.
/// </summary>
public partial class DesignSettingsTabViewModel
{
  public string CameraModeName  { get; } = "Up Zenith";
  public bool HasActiveViewport { get; } = true;

  public CometAppearanceViewModel CometAppearance { get; } = new DesignCometAppearanceViewModel();

  public DesktopBillboardsViewModel Billboards { get; } = new DesignDesktopBillboardsViewModel();

  public InputBindingsViewModel InputBindings { get; } = DesignBindings();

  public ParticleRenderingViewModel ParticleRendering { get; } = new(null, null);

  private static InputBindingsViewModel DesignBindings()
  {
    var r = new Input.InputRegistry();
    r.Register("Viewport", new Input.InputChord(Key: "V"), new Input.AppAction("viewport.switch_camera_mode"));
    r.Register("Viewport", new Input.InputChord(Key: "Tab"), new Input.AppAction("viewport.switch_camera_mode"));
    r.Register("Viewport", new Input.InputChord(Key: "NumPad5"), new Input.AppAction("viewport.toggle_projection"));
    r.CaptureDefaults();
    return new InputBindingsViewModel(r, null);
  }

  public System.Collections.ObjectModel.ObservableCollection<ViewportSettingsViewModel> ActiveViewports { get; } = new()
  {
      new DesignViewportSettingsViewModel("Viewport 1 (Perspective)", true),
      new DesignViewportSettingsViewModel("Viewport 2 (Orthographic)", false)
  };
}

public class DesignCometAppearanceViewModel : CometAppearanceViewModel
{
  public DesignCometAppearanceViewModel()
  {
    var mesh = new Models.ImportedAsset(
      1, Models.AssetKind.Mesh, "67P_churyumov", "/mock/67P.glb", 24_000, 144_000, [2, 0, 0, 0], null, null);
    var albedo = new Models.ImportedAsset(
      2, Models.AssetKind.Texture, "regolith_albedo", "/mock/67P.glb#image0", 2048, 2048, [], Models.TextureChannel.Albedo, null);
    MeshOptions.Add(mesh);
    TextureOptions.Add(new TextureOption(null, "None"));
    TextureOptions.Add(new TextureOption(albedo, albedo.Label));
    HasMeshes = true;
    IsCustomMode = true;
    SelectedMesh = mesh;
    SelectedAlbedo = TextureOptions[1];
    SelectedNormal = SelectedRoughness = SelectedAo = TextureOptions[0];
    Yaw = 30;
  }
}

public class DesignDesktopBillboardsViewModel : DesktopBillboardsViewModel
{
  public DesignDesktopBillboardsViewModel()
  {
    var tex = new Models.ImportedAsset(
      5, Models.AssetKind.Texture, "67P_2026-03-01_rosetta", "/mock/67P_tail.png", 2048, 1365, [], null, null)
    { IsDisplayable = true };
    TextureOptions.Add(tex);
    SelectedTexture = tex;
    HasTextures = true;
  }
}

